[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellSource — Expert health guidance you can trust</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ── Design Tokens (OKLCH) ─────────────────────────────── */
:root {
  --primary: oklch(52% 0.09 195);
  --primary-light: oklch(92% 0.03 195);
  --primary-lighter: oklch(96% 0.015 195);
  --primary-dark: oklch(38% 0.09 195);
  --primary-surface: oklch(97% 0.02 195);
  --accent: oklch(70% 0.15 40);
  --accent-hover: oklch(65% 0.16 40);
  --accent-light: oklch(95% 0.04 40);
  --text-primary: oklch(15% 0.02 60);
  --text-secondary: oklch(40% 0.02 60);
  --text-muted: oklch(60% 0.015 60);
  --bg: oklch(100% 0 0);
  --bg-alt: oklch(97% 0.005 195);
  --bg-card: oklch(99% 0.005 195);
  --border: oklch(91% 0.02 195);
  --border-light: oklch(95% 0.01 195);
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.06), 0 1px 2px oklch(0% 0 0 / 0.04);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.08), 0 2px 4px oklch(0% 0 0 / 0.04);
  --shadow-lg: 0 12px 32px oklch(0% 0 0 / 0.1), 0 4px 8px oklch(0% 0 0 / 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1200px;
  --header-height: 64px;
}

/* ── Reset & Base ───────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

/* ── Utility ────────────────────────────────────────────── */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-4); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* ── Focus ──────────────────────────────────────────────── */
:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }

/* ── Animations ─────────────────────────────────────────── */
@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
@keyframes fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

/* ══════════════════════════════════════════════════════════
   HEADER / NAV
   ══════════════════════════════════════════════════════════ */
.header {
  position: sticky; top: 0; z-index: 100;
  background: var(--bg);
  border-bottom: 1px solid var(--border-light);
  height: var(--header-height);
}
.header__inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 100%; gap: var(--space-4);
}
.header__logo {
  font-weight: 800; font-size: 1.35rem; letter-spacing: -0.02em;
  color: var(--primary); flex-shrink: 0;
}
.header__logo span { color: var(--text-primary); }
.header__nav { display: flex; align-items: center; gap: var(--space-1); height: 100%; }
.nav-item {
  position: relative; display: flex; align-items: center; gap: 4px;
  padding: var(--space-2) var(--space-3);
  font-size: 0.9rem; font-weight: 500; color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color 0.15s, background 0.15s;
  height: 100%;
}
.nav-item:hover, .nav-item[aria-expanded="true"] { color: var(--primary); background: var(--primary-lighter); }
.nav-item svg { width: 14px; height: 14px; transition: transform 0.2s; }
.nav-item[aria-expanded="true"] svg { transform: rotate(180deg); }
.header__actions { display: flex; align-items: center; gap: var(--space-3); flex-shrink: 0; }
.btn-subscribe {
  padding: var(--space-2) var(--space-4);
  background: var(--primary); color: #fff;
  font-size: 0.85rem; font-weight: 600;
  border-radius: var(--radius-full);
  transition: background 0.15s;
}
.btn-subscribe:hover { background: var(--primary-dark); }
.btn-signin {
  padding: var(--space-2) var(--space-3);
  font-size: 0.85rem; font-weight: 500; color: var(--text-secondary);
  border-radius: var(--radius-sm); transition: color 0.15s;
}
.btn-signin:hover { color: var(--primary); }
.hamburger { display: none; padding: var(--space-2); }

/* Mega Menu */
.mega-menu {
  position: absolute; top: var(--header-height); left: 50%; transform: translateX(-50%);
  width: min(800px, 95vw);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: var(--space-5);
  display: none; z-index: 200;
}
.nav-item[aria-expanded="true"] .mega-menu { display: block; animation: fade-in 0.15s ease-out; }
.mega-menu__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-3); }
.mega-menu__heading {
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--text-muted);
  padding-bottom: var(--space-2); margin-bottom: var(--space-2);
  border-bottom: 1px solid var(--border-light);
}
.mega-menu__link {
  display: block; padding: var(--space-1) 0;
  font-size: 0.88rem; color: var(--text-secondary);
  transition: color 0.12s;
}
.mega-menu__link:hover { color: var(--primary); }

/* ══════════════════════════════════════════════════════════
   CREDIBILITY TICKER
   ══════════════════════════════════════════════════════════ */
.ticker {
  background: var(--primary);
  color: #fff; overflow: hidden; white-space: nowrap;
  padding: var(--space-2) 0;
}
.ticker__track {
  display: inline-flex; gap: var(--space-7);
  animation: ticker-scroll 28s linear infinite;
}
.ticker__item {
  display: inline-flex; align-items: center; gap: var(--space-2);
  font-size: 0.85rem; font-weight: 500; flex-shrink: 0;
}
.ticker__item strong { font-weight: 700; font-size: 1rem; }
.ticker__dot { width: 4px; height: 4px; border-radius: 50%; background: oklch(80% 0.06 195); flex-shrink: 0; }

/* ══════════════════════════════════════════════════════════
   HERO
   ══════════════════════════════════════════════════════════ */
.hero { padding: var(--space-6) 0 var(--space-5); }
.hero__grid { display: grid; grid-template-columns: 1fr 380px; gap: var(--space-5); }
.hero__main {
  position: relative; border-radius: var(--radius-xl); overflow: hidden;
  background: oklch(85% 0.06 195); min-height: 420px;
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: var(--space-5);
}
.hero__img-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, oklch(72% 0.08 195), oklch(60% 0.1 195));
  z-index: 0;
}
.hero__img-bg::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to top, oklch(15% 0.02 60 / 0.7), oklch(15% 0.02 60 / 0.1) 60%, transparent);
}
.hero__badge {
  position: relative; z-index: 1;
  display: inline-flex; align-items: center; gap: var(--space-2);
  background: var(--accent); color: #fff;
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: var(--space-1) var(--space-3); border-radius: var(--radius-full);
  width: fit-content; margin-bottom: var(--space-3);
}
.hero__badge svg { width: 14px; height: 14px; }
.hero__title {
  position: relative; z-index: 1;
  font-size: 2rem; font-weight: 800; line-height: 1.2;
  color: #fff; margin-bottom: var(--space-2);
  letter-spacing: -0.02em;
}
.hero__subtitle {
  position: relative; z-index: 1;
  font-size: 1.05rem; color: oklch(95% 0.02 195);
  line-height: 1.5; max-width: 520px;
}

/* Trending Sidebar */
.trending { display: flex; flex-direction: column; }
.trending__heading {
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--text-muted);
  padding-bottom: var(--space-3); margin-bottom: var(--space-3);
  border-bottom: 2px solid var(--primary);
}
.trending__list { display: flex; flex-direction: column; gap: 0; flex: 1; }
.trending__item {
  padding: var(--space-3) 0;
  border-bottom: 1px solid var(--border-light);
  transition: background 0.12s;
}
.trending__item:last-child { border-bottom: none; }
.trending__item:hover { background: var(--primary-lighter); margin: 0 calc(-1 * var(--space-3)); padding-left: var(--space-3); padding-right: var(--space-3); border-radius: var(--radius-sm); }
.trending__cat {
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.06em; color: var(--primary); margin-bottom: 4px;
}
.trending__title { font-size: 0.92rem; font-weight: 600; line-height: 1.4; color: var(--text-primary); }

/* ══════════════════════════════════════════════════════════
   NEWSLETTER CTA
   ══════════════════════════════════════════════════════════ */
.newsletter-cta {
  background: linear-gradient(135deg, var(--primary-dark), var(--primary));
  padding: var(--space-6) 0;
}
.newsletter-cta__inner {
  display: flex; align-items: center; justify-content: space-between; gap: var(--space-5);
}
.newsletter-cta__text { max-width: 480px; }
.newsletter-cta__heading { font-size: 1.5rem; font-weight: 700; color: #fff; margin-bottom: var(--space-2); }
.newsletter-cta__body { font-size: 0.95rem; color: oklch(90% 0.03 195); line-height: 1.5; }
.newsletter-cta__form { display: flex; gap: var(--space-2); flex-shrink: 0; }
.newsletter-cta__input {
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-full);
  border: 1px solid oklch(70% 0.05 195);
  background: oklch(100% 0 0 / 0.15);
  color: #fff; font-size: 0.9rem; width: 280px;
  backdrop-filter: blur(4px);
}
.newsletter-cta__input::placeholder { color: oklch(80% 0.04 195); }
.newsletter-cta__input:focus { outline: none; border-color: oklch(85% 0.06 195); background: oklch(100% 0 0 / 0.2); }
.newsletter-cta__btn {
  padding: var(--space-3) var(--space-5);
  background: var(--accent); color: #fff;
  font-size: 0.9rem; font-weight: 600;
  border-radius: var(--radius-full);
  transition: background 0.15s; white-space: nowrap;
}
.newsletter-cta__btn:hover { background: var(--accent-hover); }
.newsletter-cta__privacy { font-size: 0.75rem; color: oklch(80% 0.04 195); margin-top: var(--space-2); text-align: right; }

/* ══════════════════════════════════════════════════════════
   HEALTH TOPICS CAROUSEL
   ══════════════════════════════════════════════════════════ */
.health-topics { padding: var(--space-7) 0; }
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--space-5); }
.section-title { font-size: 1.35rem; font-weight: 700; letter-spacing: -0.01em; }
.section-link {
  font-size: 0.85rem; font-weight: 600; color: var(--primary);
  display: inline-flex; align-items: center; gap: 4px;
  transition: gap 0.15s;
}
.section-link:hover { gap: 8px; }
.section-link svg { width: 16px; height: 16px; }
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex; gap: var(--space-4);
  overflow-x: auto; scroll-behavior: smooth;
  -ms-overflow-style: none; scrollbar-width: none;
  padding: var(--space-2) 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.topic-card {
  flex-shrink: 0; display: flex; flex-direction: column; align-items: center;
  gap: var(--space-2); width: 150px;
  text-align: center; cursor: pointer;
  transition: transform 0.2s;
}
.topic-card:hover { transform: translateY(-4px); }
.topic-card__img {
  width: 110px; height: 110px; border-radius: 50%;
  background: var(--primary-light);
  border: 3px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: 2.2rem;
  transition: border-color 0.2s, box-shadow 0.2s;
  overflow: hidden;
}
.topic-card:hover .topic-card__img { border-color: var(--primary); box-shadow: 0 0 0 4px var(--primary-light); }
.topic-card__label { font-size: 0.85rem; font-weight: 600; color: var(--text-primary); }
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--bg); border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  display: flex; align-items: center; justify-content: center;
  z-index: 5; transition: background 0.15s, box-shadow 0.15s;
}
.carousel-arrow:hover { background: var(--primary-light); box-shadow: var(--shadow-md); }
.carousel-arrow svg { width: 18px; height: 18px; color: var(--text-secondary); }
.carousel-arrow--left { left: -16px; }
.carousel-arrow--right { right: -16px; }

/* ══════════════════════════════════════════════════════════
   HEALTH TOOLS
   ══════════════════════════════════════════════════════════ */
.health-tools { padding: var(--space-6) 0; background: var(--bg-alt); }
.tools-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-5); }
.tools-section {
  background: var(--bg); border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  padding: var(--space-5);
}
.tools-section__icon {
  width: 44px; height: 44px; border-radius: var(--radius-md);
  background: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: var(--space-3); font-size: 1.2rem;
}
.tools-section__heading { font-size: 1.15rem; font-weight: 700; margin-bottom: var(--space-2); }
.tools-section__body { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.5; margin-bottom: var(--space-4); }
.tools-section__cta {
  display: inline-flex; align-items: center; gap: var(--space-2);
  font-size: 0.88rem; font-weight: 600; color: var(--primary);
  margin-bottom: var(--space-4);
  transition: gap 0.15s;
}
.tools-section__cta:hover { gap: 10px; }
.tools-section__cta svg { width: 16px; height: 16px; }
.tools-list { display: flex; flex-direction: column; gap: var(--space-2); }
.tool-item {
  display: flex; align-items: center; gap: var(--space-3);
  padding: var(--space-3); border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
  transition: border-color 0.15s, background 0.15s;
  cursor: pointer;
}
.tool-item:hover { border-color: var(--primary); background: var(--primary-lighter); }
.tool-item__icon {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  background: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem; flex-shrink: 0;
}
.tool-item__text { flex: 1; }
.tool-item__name { font-size: 0.88rem; font-weight: 600; }
.tool-item__desc { font-size: 0.78rem; color: var(--text-muted); margin-top: 2px; line-height: 1.35; }
.tool-item__arrow { color: var(--text-muted); transition: color 0.15s, transform 0.15s; }
.tool-item:hover .tool-item__arrow { color: var(--primary); transform: translateX(2px); }
.tool-item__arrow svg { width: 16px; height: 16px; }

/* ══════════════════════════════════════════════════════════
   RECOMMENDED READS
   ══════════════════════════════════════════════════════════ */
.recommended { padding: var(--space-7) 0; }
.tabs { display: flex; gap: var(--space-2); margin-bottom: var(--space-5); flex-wrap: wrap; }
.tab {
  padding: var(--space-2) var(--space-4);
  font-size: 0.85rem; font-weight: 500; color: var(--text-secondary);
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  transition: all 0.15s;
}
.tab:hover { border-color: var(--primary); color: var(--primary); }
.tab.active {
  background: var(--primary); color: #fff;
  border-color: var(--primary);
}
.articles-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-4);
}
.article-card {
  background: var(--bg-card); border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  overflow: hidden; transition: box-shadow 0.2s, transform 0.2s;
}
.article-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.article-card__img {
  height: 180px; background: var(--primary-light);
  position: relative; overflow: hidden;
}
.article-card__img-inner {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 2rem;
}
.article-card__body { padding: var(--space-4); }
.article-card__cat {
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.06em; color: var(--primary); margin-bottom: var(--space-2);
}
.article-card__title {
  font-size: 1rem; font-weight: 600; line-height: 1.4;
  color: var(--text-primary);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical;
  overflow: hidden;
}
.tab-content { display: none; animation: fade-in 0.2s ease-out; }
.tab-content.active { display: block; }

/* ══════════════════════════════════════════════════════════
   TRUST PILLARS
   ══════════════════════════════════════════════════════════ */
.trust { padding: var(--space-7) 0; background: var(--bg-alt); }
.trust__heading {
  text-align: center; font-size: 1.5rem; font-weight: 700;
  margin-bottom: var(--space-6); max-width: 540px;
  margin-left: auto; margin-right: auto; letter-spacing: -0.01em;
}
.pillars-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-4); }
.pillar {
  text-align: center; padding: var(--space-5) var(--space-4);
  background: var(--bg); border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  transition: box-shadow 0.2s;
}
.pillar:hover { box-shadow: var(--shadow-md); }
.pillar__icon {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto var(--space-3); font-size: 1.4rem;
}
.pillar__title { font-size: 1rem; font-weight: 700; margin-bottom: var(--space-2); }
.pillar__desc { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.5; }

/* ══════════════════════════════════════════════════════════
   FEATURED PROGRAMS
   ══════════════════════════════════════════════════════════ */
.programs { padding: var(--space-7) 0; }
.programs-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-4); }
.program-card {
  border-radius: var(--radius-lg); overflow: hidden;
  border: 1px solid var(--border-light);
  transition: box-shadow 0.2s, transform 0.2s;
  cursor: pointer;
}
.program-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.program-card__img {
  height: 160px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
}
.program-card__body { padding: var(--space-3) var(--space-4); }
.program-card__title { font-size: 0.92rem; font-weight: 600; line-height: 1.35; }

/* ══════════════════════════════════════════════════════════
   LATEST VIDEOS
   ══════════════════════════════════════════════════════════ */
.videos { padding: var(--space-7) 0; background: var(--bg-alt); }
.videos-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-4); }
.video-card {
  border-radius: var(--radius-lg); overflow: hidden;
  border: 1px solid var(--border-light);
  background: var(--bg); transition: box-shadow 0.2s, transform 0.2s;
  cursor: pointer;
}
.video-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.video-card__img {
  height: 160px; position: relative;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
}
.video-card__play {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  background: oklch(15% 0.02 60 / 0.3);
  opacity: 0; transition: opacity 0.2s;
}
.video-card:hover .video-card__play { opacity: 1; }
.video-card__play-circle {
  width: 52px; height: 52px; border-radius: 50%;
  background: #fff; display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-md);
}
.video-card__play-circle svg { width: 20px; height: 20px; margin-left: 3px; color: var(--primary); }
