<script>
// ── Mega Menu ────────────────────────────────────────────
(function() {
  const navItems = document.querySelectorAll('.nav-item[data-dropdown]');

  navItems.forEach(item => {
    item.addEventListener('click', function(e) {
      e.stopPropagation();
      const isExpanded = this.getAttribute('aria-expanded') === 'true';
      closeAllMenus();
      if (!isExpanded) {
        this.setAttribute('aria-expanded', 'true');
      }
    });

    item.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        this.click();
      }
    });
  });

  function closeAllMenus() {
    navItems.forEach(item => item.setAttribute('aria-expanded', 'false'));
  }

  document.addEventListener('click', function(e) {
    if (!e.target.closest('.nav-item')) {
      closeAllMenus();
    }
  });

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      closeAllMenus();
    }
  });
})();

// ── Recommended Reads Tabs ───────────────────────────────
(function() {
  const tabs = document.querySelectorAll('#readsTabs .tab');
  const panels = document.querySelectorAll('.tab-content');

  tabs.forEach(tab => {
    tab.addEventListener('click', function() {
      tabs.forEach(t => { t.classList.remove('active'); t.setAttribute('aria-selected', 'false'); });
      panels.forEach(p => p.classList.remove('active'));
      this.classList.add('active');
      this.setAttribute('aria-selected', 'true');
      const target = document.getElementById('tab-' + this.dataset.tab);
      if (target) target.classList.add('active');
    });
  });
})();

// ── Health Topics Carousel ────────────────────────────────
(function() {
  const track = document.getElementById('topicCarousel');
  const prev = document.getElementById('topicPrev');
  const next = document.getElementById('topicNext');
  const scrollAmt = 200;

  if (prev && next && track) {
    prev.addEventListener('click', () => track.scrollBy({ left: -scrollAmt, behavior: 'smooth' }));
    next.addEventListener('click', () => track.scrollBy({ left: scrollAmt, behavior: 'smooth' }));
  }
})();

